class Solution {
public:
    bool checkValidCuts(int n, vector<vector<int>>& rectangles) {
        auto canCut = [](vector<pair<int, int>>& intervals) {
            sort(intervals.begin(), intervals.end());
            int sections = 0;
            int maxEnd = intervals[0].second;
            for (size_t i = 1; i < intervals.size(); ++i) {
                if (intervals[i].first >= maxEnd) {
                    sections++;
                    maxEnd = intervals[i].second;
                } else {
                    maxEnd = max(maxEnd, intervals[i].second);
                }
            }
            return sections >= 2;
        };

        vector<pair<int, int>> xIntervals, yIntervals;
        for (const auto& r : rectangles) {
            xIntervals.push_back({r[0], r[2]});
            yIntervals.push_back({r[1], r[3]});
        }
        return canCut(xIntervals) || canCut(yIntervals);
    }
};

class Solution {
    public boolean checkValidCuts(int n, int[][] rectangles) {
        int m = rectangles.length;
        int[][] xIntervals = new int[m][2];
        int[][] yIntervals = new int[m][2];
        for (int i = 0; i < m; ++i) {
            xIntervals[i][0] = rectangles[i][0];
            xIntervals[i][1] = rectangles[i][2];
            yIntervals[i][0] = rectangles[i][1];
            yIntervals[i][1] = rectangles[i][3];
        }
        return canCut(xIntervals) || canCut(yIntervals);
    }

    private boolean canCut(int[][] intervals) {
        Arrays.sort(intervals, (a, b) -> a[0] != b[0] ? Integer.compare(a[0], b[0]) : Integer.compare(a[1], b[1]));
        int sections = 0;
        int maxEnd = intervals[0][1];
        for (int i = 1; i < intervals.length; ++i) {
            if (intervals[i][0] >= maxEnd) {
                sections++;
                maxEnd = intervals[i][1];
            } else {
                maxEnd = Math.max(maxEnd, intervals[i][1]);
            }
        }
        return sections >= 2;
    }
}

var checkValidCuts = function(n, rectangles) {
    const canCut = (intervals) => {
        intervals.sort((a, b) => a[0] !== b[0] ? a[0] - b[0] : a[1] - b[1]);
        let sections = 0;
        let maxEnd = intervals[0][1];
        for (let i = 1; i < intervals.length; ++i) {
