                sections++;
                maxEnd = intervals[i][1];
            } else {
                maxEnd = Math.max(maxEnd, intervals[i][1]);
            }
        }
        return sections >= 2;
    };

    const xIntervals = rectangles.map(r => [r[0], r[2]]);
